INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000017d',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss German social policy","Use Sozialpolitik vocabulary at B2","Understand welfare state concepts"],"explanation":{"intro":"German social policy vocabulary at B2 covers the welfare state, social insurance, and policy debates.","culturalNote":"Germany has one of the world''s most developed Sozialstaaten (welfare states). The Sozialversicherung (social insurance) covers four pillars: Krankenversicherung (health), Rentenversicherung (pension), Pflegeversicherung (long-term care), Arbeitslosenversicherung (unemployment). Hartz IV (now Bürgergeld) was the landmark welfare reform. Soziale Gerechtigkeit (social justice) is a central political concept."},"examples":[{"german":"Das deutsche Sozialsystem soll sicherstellen, dass niemand in extreme Armut fällt.","english":"The German social system is intended to ensure that no one falls into extreme poverty."},{"german":"Die Reform des Arbeitslosengeldes war politisch umstritten, zeigte aber langfristig Wirkung.","english":"The reform of unemployment benefit was politically controversial but showed long-term effect."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss German social policy, welfare state concepts, and social policy debates at B2."}}',
'{"items":[{"word":"der Sozialstaat","translation":"welfare state","pronunciation":"dayr zo-tsee-AHL-shtaht","example":"Sozialstaat."},{"word":"die Pflegeversicherung","translation":"long-term care insurance","pronunciation":"dee PFLAY-geh-fer-zikh-eh-roong","example":"Pflegeversicherung."},{"word":"umstritten","translation":"controversial/disputed","pronunciation":"OOM-shrit-en","example":"Politisch umstritten."},{"word":"sicherstellen","translation":"to ensure/guarantee","pronunciation":"ZIK-her-shtel-en","example":"Sicherstellen dass."},{"word":"das Bürgergeld","translation":"citizen''s income (welfare)","pronunciation":"dahs BÜR-ger-gelt","example":"Bürgergeld beziehen."},{"word":"langfristig","translation":"long-term","pronunciation":"LANG-fris-tikh","example":"Langfristig Wirkung zeigen."}]}',
'{"title":"Sicherstellen dass — to ensure that","pattern":"etwas stellt sicher, dass + V-final clause (ensures that)","explanation":"Sicherstellen dass = to ensure that. Separable: das System stellt sicher, dass... Perfect: hat sichergestellt. Also: gewährleisten dass (to guarantee that — more formal), dafür sorgen dass (to make sure that — everyday). Die Sicherstellung = the ensuring/securing. Compare: sichern (to secure), absichern (to safeguard — more physical sense).","examples":[{"sentence":"Die Gesetzgebung stellt sicher, dass alle Bürger gleiche Rechte haben.","translation":"The legislation ensures that all citizens have equal rights."},{"sentence":"Eltern müssen sicherstellen, dass ihre Kinder zur Schule gehen.","translation":"Parents must ensure that their children go to school."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Bürgergeld'' is the German?","options":["citizen''s income/welfare benefit","basic income","social wage","citizens''s salary"],"correctAnswer":"citizen''s income/welfare benefit"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The German social system is intended to ensure that no one falls into extreme poverty.","options":["Das deutsche Sozialsystem soll sicherstellen, dass niemand in extreme Armut fällt.","Das Sozialsystem verhindert Armut.","In Deutschland gibt es kein extremes Armut.","Das Sozialsystem hilft armen Menschen."],"correctAnswer":"Das deutsche Sozialsystem soll sicherstellen, dass niemand in extreme Armut fällt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Gesetzgebung stellt sicher, dass alle Bürger gleiche Rechte ___.","options":["haben","hätten","gehabt haben","zu haben"],"correctAnswer":"haben"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Parents must ensure that their children go to school","wordBankItems":["Eltern","müssen","sicherstellen",",","dass","ihre","Kinder","zur","Schule","gehen","."],"correctAnswer":"Eltern müssen sicherstellen , dass ihre Kinder zur Schule gehen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Umstritten'' means?","options":["controversial/disputed","debated","contested","questionable"],"correctAnswer":"controversial/disputed"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000017e',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss German education at B2","Use Bildungssystem vocabulary","Talk about education reform and inequality"],"explanation":{"intro":"Education system vocabulary at B2 covers school structure, educational inequality, and reform debates.","culturalNote":"Germany has a three-track school system: Hauptschule (basic), Realschule (intermediate), Gymnasium (academic). PISA studies showed Germany has high educational inequality — Bildungsgerechtigkeit (educational equity) remains a major debate. All-day schools (Ganztagsschulen) have expanded. Bildung (education as personal formation) vs. Ausbildung (vocational training) is a key German distinction."},"examples":[{"german":"Die Bildungsgerechtigkeit ist in Deutschland nach wie vor eine der größten Herausforderungen.","english":"Educational equity is still one of the greatest challenges in Germany."},{"german":"Das dreigliedrige Schulsystem wird oft kritisiert, weil es früh über Lebenschancen entscheidet.","english":"The three-track school system is often criticised because it decides life chances early on."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the German education system, educational equity, and reform debates at B2."}}',
'{"items":[{"word":"die Bildungsgerechtigkeit","translation":"educational equity","pronunciation":"dee BIL-doonks-geh-rekh-tikh-kyt","example":"Bildungsgerechtigkeit."},{"word":"dreigliedrig","translation":"three-track/three-tiered","pronunciation":"DRY-glee-drikh","example":"Dreigliedriges Schulsystem."},{"word":"die Herausforderung","translation":"challenge","pronunciation":"dee heh-ROWSS-for-deh-roong","example":"Herausforderungen."},{"word":"die Lebenschance","translation":"life chance/opportunity","pronunciation":"dee LAY-ben-shan-seh","example":"Lebenschancen."},{"word":"nach wie vor","translation":"still/as ever","pronunciation":"nakh vee for","example":"Nach wie vor wichtig."},{"word":"kritisieren","translation":"to criticise","pronunciation":"kri-tee-ZEER-en","example":"Das System kritisieren."}]}',
'{"title":"Nach wie vor — still/as ever (formal)","pattern":"nach wie vor + adjective/verb phrase = still, as ever, continues to (formal written German)","explanation":"Nach wie vor = still, as ever. Formal written German alternative to immer noch. Nach wie vor relevant = still relevant. Die Frage ist nach wie vor offen = the question remains open. The phrase implies that despite passage of time or expectation of change, the situation persists. Immer noch = more neutral/spoken equivalent. Bis heute = to this day (somewhat more emphatic).","examples":[{"sentence":"Das Problem ist nach wie vor ungelöst.","translation":"The problem is still unresolved."},{"sentence":"Der Vertrag gilt nach wie vor.","translation":"The contract is still valid."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Nach wie vor'' is the formal equivalent of?","options":["immer noch (still)","bisher (so far)","noch immer (still — emphasised)","neuerdings (recently)"],"correctAnswer":"immer noch (still)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Educational equity is still one of the greatest challenges in Germany.","options":["Die Bildungsgerechtigkeit ist in Deutschland nach wie vor eine der größten Herausforderungen.","Bildung ist immer noch ungerecht in Deutschland.","Deutschland hat nach wie vor Bildungsprobleme.","Bildungsgerechtigkeit bleibt eine Herausforderung."],"correctAnswer":"Die Bildungsgerechtigkeit ist in Deutschland nach wie vor eine der größten Herausforderungen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Problem ist nach wie vor ___.","options":["ungelöst","nicht gelöst","offen","unbehoben"],"correctAnswer":"ungelöst"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The contract is still valid","wordBankItems":["Der","Vertrag","gilt","nach","wie","vor","."],"correctAnswer":"Der Vertrag gilt nach wie vor ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Herausforderung'' means?","options":["challenge","task","problem","demand"],"correctAnswer":"challenge"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000017f',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss university life in Germany","Use Hochschule vocabulary at B2","Talk about academic study and degrees"],"explanation":{"intro":"University vocabulary at B2 covers academic study, German higher education structure, and student life.","culturalNote":"Germany has around 400 Hochschulen (universities and universities of applied sciences). Most are public and tuition-free (only Baden-Württemberg charges fees for some). The Bologna Process standardised degrees: Bachelor (BA), Master (MA), Doktor (PhD). Academic title use is formal: Prof. Dr. Müller is how you address a professor. The Studentenwerk (student services) provides subsidised Mensen (canteens) and student housing."},"examples":[{"german":"Nach dem Bachelor-Abschluss entschied sie sich für ein Masterstudium im Ausland.","english":"After completing her Bachelor''s degree she decided on a Master''s programme abroad."},{"german":"An deutschen Hochschulen ist das Studium weitgehend kostenfrei, was attraktiv für internationale Studierende ist.","english":"At German universities study is largely free of charge, which is attractive for international students."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss German university life, academic structure, and student vocabulary at B2."}}',
'{"items":[{"word":"die Hochschule","translation":"university/higher education institution","pronunciation":"dee HOHKH-shoo-leh","example":"An der Hochschule."},{"word":"weitgehend","translation":"largely/mostly/for the most part","pronunciation":"VYT-gay-end","example":"Weitgehend kostenfrei."},{"word":"die Mensa","translation":"student canteen","pronunciation":"dee MEN-zah","example":"In der Mensa essen."},{"word":"das Ausland","translation":"foreign country/abroad","pronunciation":"dahs OWS-lant","example":"Im Ausland studieren."},{"word":"der Abschluss","translation":"degree/qualification","pronunciation":"dayr AP-shloos","example":"Den Abschluss machen."},{"word":"das Studiengang","translation":"degree programme","pronunciation":"dahs SHTOO-dee-en-gang","example":"Studiengang wählen."}]}',
'{"title":"Sich entscheiden für — to decide on/opt for","pattern":"sich entscheiden für + accusative (to decide on, opt for, choose)","explanation":"Sich entscheiden für + accusative = to decide on, opt for. Sie entschied sich für ein Masterstudium = She opted for a Master''s programme. Perfect: hat sich entschieden. Sich entscheiden zwischen (two options): sich entscheiden zwischen A und B. The decision is personal and deliberate. Compare: beschließen (to decide/resolve — more formal, often for groups), sich für etwas entschließen (to resolve to do something — more weighty).","examples":[{"sentence":"Er hat sich für den Studiengang Informatik entschieden.","translation":"He has opted for the computer science degree programme."},{"sentence":"Viele Studenten entscheiden sich heutzutage für einen Auslandsaufenthalt.","translation":"Many students nowadays opt for a period abroad."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Weitgehend'' means?","options":["largely/for the most part","far-reaching","wide-ranging","extensively"],"correctAnswer":"largely/for the most part"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"After completing her Bachelor''s degree she decided on a Master''s programme abroad.","options":["Nach dem Bachelor-Abschluss entschied sie sich für ein Masterstudium im Ausland.","Sie beschloss nach dem Bachelor-Abschluss ins Ausland zu gehen.","Nach dem Bachelor machte sie einen Master.","Ihr Bachelor war erfolgreich und sie wählte ein Masterstudium."],"correctAnswer":"Nach dem Bachelor-Abschluss entschied sie sich für ein Masterstudium im Ausland."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Er hat sich für den Studiengang Informatik ___.","options":["entschieden","entschied","entscheidet","entschlossen"],"correctAnswer":"entschieden"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Many students nowadays opt for a period abroad","wordBankItems":["Viele","Studenten","entscheiden","sich","heutzutage","für","einen","Auslandsaufenthalt","."],"correctAnswer":"Viele Studenten entscheiden sich heutzutage für einen Auslandsaufenthalt ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Sich entscheiden für'' takes which case?","options":["accusative","dative","genitive","nominative"],"correctAnswer":"accusative"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000180',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss health policy in Germany","Use Gesundheitspolitik vocabulary","Talk about healthcare reform at B2"],"explanation":{"intro":"Health policy vocabulary at B2 covers the German health system, reform pressures, and key concepts.","culturalNote":"Germany has a dual health insurance system: Gesetzliche Krankenversicherung (GKV — statutory health insurance, ~90% of population) and Private Krankenversicherung (PKV — private health insurance, ~10%). Krankenkassen (health insurance funds) compete. Rising Beiträge (contributions), Fachkräftemangel (skilled worker shortage) in healthcare, and hospital reform are current issues."},"examples":[{"german":"Das duale Krankenversicherungssystem steht vor erheblichem Reformdruck.","english":"The dual health insurance system faces considerable pressure for reform."},{"german":"Der Fachkräftemangel im Pflegebereich hat sich in den letzten Jahren erheblich verschärft.","english":"The shortage of skilled workers in nursing has intensified considerably in recent years."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss German health policy, insurance system, and healthcare debates at B2."}}',
'{"items":[{"word":"dual","translation":"dual","pronunciation":"doo-AHL","example":"Duales System."},{"word":"der Reformdruck","translation":"pressure for reform","pronunciation":"dayr reh-FORM-drook","example":"Unter Reformdruck."},{"word":"sich verschärfen","translation":"to intensify/worsen","pronunciation":"zikh fer-SHÄR-fen","example":"Sich verschärft."},{"word":"der Fachkräftemangel","translation":"skilled worker shortage","pronunciation":"dayr FAKH-kräf-teh-man-gel","example":"Fachkräftemangel."},{"word":"die Krankenkasse","translation":"health insurance fund","pronunciation":"dee KRANK-en-kas-eh","example":"Bei der Krankenkasse."},{"word":"erheblich","translation":"considerable/significant","pronunciation":"er-HAIP-likh","example":"Erheblich gestiegen."}]}',
'{"title":"Sich verschärfen — to intensify/worsen","pattern":"etwas verschärft sich (something intensifies, worsens — reflexive)","explanation":"Sich verschärfen = to intensify, worsen (of problems, situations). Die Lage verschärft sich = The situation is worsening. Die Krise hat sich verschärft = The crisis has intensified. Synonyms: sich zuspitzen (to come to a head — more dramatic), sich verschlechtern (to deteriorate — broader), eskalieren (to escalate). Die Verschärfung = intensification. Also: das Gesetz verschärfen = to tighten (a law — transitive, non-reflexive).","examples":[{"sentence":"Der Konflikt hat sich in den letzten Wochen verschärft.","translation":"The conflict has intensified in recent weeks."},{"sentence":"Die Wohnungsnot verschärft sich in Großstädten.","translation":"The housing shortage is worsening in cities."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Sich verschärfen'' means?","options":["to intensify/worsen","to sharpen","to tighten","to harden"],"correctAnswer":"to intensify/worsen"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The shortage of skilled workers in nursing has intensified considerably in recent years.","options":["Der Fachkräftemangel im Pflegebereich hat sich in den letzten Jahren erheblich verschärft.","Es gibt immer weniger Pflegekräfte.","Der Pflegebereich leidet unter Fachkräftemangel.","Erheblich weniger Pflegekräfte gibt es heute."],"correctAnswer":"Der Fachkräftemangel im Pflegebereich hat sich in den letzten Jahren erheblich verschärft."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Konflikt hat sich in den letzten Wochen ___.","options":["verschärft","verschärfen","verschärfend","verschärft hat"],"correctAnswer":"verschärft"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The housing shortage is worsening in cities","wordBankItems":["Die","Wohnungsnot","verschärft","sich","in","Großstädten","."],"correctAnswer":"Die Wohnungsnot verschärft sich in Großstädten ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Erheblich'' means?","options":["considerable/significant","elevated","serious","substantial"],"correctAnswer":"considerable/significant"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000181',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss social change","Use sozialer Wandel vocabulary at B2","Analyse trends and transformation"],"explanation":{"intro":"Social change vocabulary at B2 covers demographic change, cultural shifts, and societal transformation.","culturalNote":"Germany faces major soziale Veränderungen: demographic change (Demografischer Wandel — ageing society), changing family structures (Patchworkfamilien, Einpersonenhaushalte), value change (Wertewandel — shift from traditional to post-materialist values), and digitisation of daily life."},"examples":[{"german":"Der demografische Wandel stellt das Rentensystem vor wachsende Herausforderungen.","english":"Demographic change poses growing challenges to the pension system."},{"german":"Der Wertewandel der letzten Jahrzehnte hat das gesellschaftliche Leben grundlegend verändert.","english":"The value change of recent decades has fundamentally transformed social life."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss social change, demographic trends, and societal transformation at B2."}}',
'{"items":[{"word":"der demografische Wandel","translation":"demographic change","pronunciation":"dayr deh-mo-GRAHF-ee-sheh VAN-del","example":"Demografischer Wandel."},{"word":"der Wertewandel","translation":"value change","pronunciation":"dayr VER-teh-van-del","example":"Wertewandel."},{"word":"grundlegend","translation":"fundamental/radical","pronunciation":"GROONT-lay-gend","example":"Grundlegend verändert."},{"word":"verändern","translation":"to change/transform","pronunciation":"fer-EN-dern","example":"Etwas verändern."},{"word":"die Patchworkfamilie","translation":"blended/patchwork family","pronunciation":"dee PACH-work-fah-mee-lee-eh","example":"Patchworkfamilien."},{"word":"wachsend","translation":"growing/increasing","pronunciation":"VAKS-end","example":"Wachsende Herausforderungen."}]}',
'{"title":"Grundlegend — fundamentally/radically (B2 intensifier)","pattern":"grundlegend + past participle = fundamentally changed/transformed (formal written)","explanation":"Grundlegend as adverb/intensifier = fundamentally, radically. Grundlegend verändern = to fundamentally change. Grundlegend neu gestalten = to fundamentally redesign. In formal writing, this strengthens the claim that change is deep, not superficial. Synonyms: tiefgreifend (deep-reaching), nachhaltig (lasting — sometimes = sustainably in different context), von Grund auf (from the ground up).","examples":[{"sentence":"Das Gesetz hat die Rechtslage grundlegend verändert.","translation":"The law has fundamentally changed the legal situation."},{"sentence":"Die Digitalisierung hat die Arbeitswelt grundlegend umgestaltet.","translation":"Digitisation has fundamentally reshaped the working world."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Grundlegend'' means?","options":["fundamental/radical","basic","essential","profound"],"correctAnswer":"fundamental/radical"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The value change of recent decades has fundamentally transformed social life.","options":["Der Wertewandel der letzten Jahrzehnte hat das gesellschaftliche Leben grundlegend verändert.","In den letzten Jahrzehnten hat sich der Wertewandel durchgesetzt.","Das gesellschaftliche Leben hat sich sehr verändert.","Wertewandel hat zu grundlegenden Veränderungen geführt."],"correctAnswer":"Der Wertewandel der letzten Jahrzehnte hat das gesellschaftliche Leben grundlegend verändert."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Digitalisierung hat die Arbeitswelt grundlegend ___.","options":["umgestaltet","verändert","erneuert","reformiert"],"correctAnswer":"umgestaltet"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The law has fundamentally changed the legal situation","wordBankItems":["Das","Gesetz","hat","die","Rechtslage","grundlegend","verändert","."],"correctAnswer":"Das Gesetz hat die Rechtslage grundlegend verändert ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Tiefgreifend'' is a synonym for ''grundlegend'' meaning?","options":["deep-reaching/profound","deep-digging","deeply felt","intensive"],"correctAnswer":"deep-reaching/profound"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000182',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss migration at B2","Use advanced migration vocabulary","Talk about migration policy and public debate"],"explanation":{"intro":"B2 migration vocabulary covers policy, integration, and the political discourse around migration in Germany.","culturalNote":"Germany became a major destination country for migration: Gastarbeiter in the 1960s, EU-internal migration, refugees (2015 Refugee Crisis — Flüchtlingskrise), and skilled worker immigration. Key concepts: Aufenthaltserlaubnis (residence permit), Asylrecht (right of asylum in the Grundgesetz), Abschiebung (deportation), sichere Herkunftsstaaten (safe countries of origin)."},"examples":[{"german":"Das Recht auf Asyl ist im Grundgesetz verankert und kann nur unter strengen Voraussetzungen eingeschränkt werden.","english":"The right to asylum is enshrined in the Basic Law and can only be restricted under strict conditions."},{"german":"Die gesellschaftliche Debatte über Migration ist vielschichtig und polarisiert.","english":"The social debate on migration is multilayered and polarising."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss migration, asylum, and immigration policy at B2."}}',
'{"items":[{"word":"verankern","translation":"to enshrine/anchor","pronunciation":"fer-AN-kern","example":"Im Grundgesetz verankert."},{"word":"die Voraussetzung","translation":"condition/prerequisite","pronunciation":"dee for-OWS-zet-soong","example":"Unter strengen Voraussetzungen."},{"word":"vielschichtig","translation":"multilayered/complex","pronunciation":"FEEL-shikh-tikh","example":"Vielschichtige Debatte."},{"word":"polarisieren","translation":"to polarise","pronunciation":"po-lah-ree-ZEER-en","example":"Die Gesellschaft polarisieren."},{"word":"das Asylrecht","translation":"right of asylum","pronunciation":"dahs ah-ZÜHL-rekht","example":"Das Asylrecht."},{"word":"die Abschiebung","translation":"deportation","pronunciation":"dee AP-shee-boong","example":"Abschiebung."}]}',
'{"title":"Verankert sein in — to be enshrined/anchored in","pattern":"etwas ist in + dative verankert = something is enshrined in, embedded in (legal/constitutional language)","explanation":"Verankern in + dative = to anchor/enshrine in. Das Recht ist im Grundgesetz verankert = The right is enshrined in the Basic Law. Passive: verankert sein in. Die Verankerung (enshrinement, anchoring). Used for values, rights, norms embedded in documents or culture. Also: in der Verfassung verankert (enshrined in the constitution), im Gesetz verankert (enshrined in law), kulturell verankert (culturally embedded).","examples":[{"sentence":"Die Meinungsfreiheit ist in der deutschen Verfassung fest verankert.","translation":"Freedom of expression is firmly enshrined in the German constitution."},{"sentence":"Diese Werte sind tief in der Gesellschaft verankert.","translation":"These values are deeply embedded in society."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Vielschichtig'' means?","options":["multilayered/complex","many-layered","multifaceted","manifold"],"correctAnswer":"multilayered/complex"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The right to asylum is enshrined in the Basic Law and can only be restricted under strict conditions.","options":["Das Recht auf Asyl ist im Grundgesetz verankert und kann nur unter strengen Voraussetzungen eingeschränkt werden.","Das Asylrecht steht im Grundgesetz und gilt für alle.","Im Grundgesetz ist Asyl geregelt.","Asylrecht ist ein Grundrecht."],"correctAnswer":"Das Recht auf Asyl ist im Grundgesetz verankert und kann nur unter strengen Voraussetzungen eingeschränkt werden."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Meinungsfreiheit ist in der deutschen Verfassung fest ___.","options":["verankert","verankert worden","verankert sein","zu verankern"],"correctAnswer":"verankert"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: These values are deeply embedded in society","wordBankItems":["Diese","Werte","sind","tief","in","der","Gesellschaft","verankert","."],"correctAnswer":"Diese Werte sind tief in der Gesellschaft verankert ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Voraussetzung'' means?","options":["condition/prerequisite","requirement","assumption","precondition"],"correctAnswer":"condition/prerequisite"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000183',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss integration at B2","Use Integration vocabulary","Talk about social cohesion and belonging"],"explanation":{"intro":"Integration vocabulary at B2 covers social cohesion, belonging, and integration policy debates.","culturalNote":"Integrationspolitik is a major policy area in Germany. Concepts: Leitkultur (dominant/guiding culture — controversial), Multikulturalismus (multiculturalism), Parallelgesellschaft (parallel society), Integrationskurs (integration course — mandatory language+civics classes for immigrants), Einbürgerung (naturalisation). The Integrationsgipfel (integration summit) is an annual government event."},"examples":[{"german":"Gelingende Integration erfordert Anstrengungen sowohl von Seiten der Aufnahmegesellschaft als auch der Zugewanderten.","english":"Successful integration requires efforts from both the receiving society and those who have immigrated."},{"german":"Sprachkenntnisse gelten als Schlüssel zur gesellschaftlichen Teilhabe.","english":"Language skills are regarded as the key to social participation."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss integration, social cohesion, and participation in German society at B2."}}',
'{"items":[{"word":"gelingend","translation":"successful/working","pronunciation":"geh-LIN-gend","example":"Gelingende Integration."},{"word":"die Teilhabe","translation":"participation/inclusion","pronunciation":"dee TYL-hah-beh","example":"Gesellschaftliche Teilhabe."},{"word":"die Aufnahmegesellschaft","translation":"receiving/host society","pronunciation":"dee OWF-nah-meh-geh-zel-shaft","example":"Die Aufnahmegesellschaft."},{"word":"die Anstrengung","translation":"effort/exertion","pronunciation":"dee AN-shtreng-oong","example":"Anstrengungen unternehmen."},{"word":"die Einbürgerung","translation":"naturalisation","pronunciation":"dee YN-bür-geh-roong","example":"Einbürgerung beantragen."},{"word":"die Leitkultur","translation":"dominant/guiding culture (controversial)","pronunciation":"dee LYT-kool-toor","example":"Leitkultur."}]}',
'{"title":"Sowohl...als auch — both...and (formal)","pattern":"sowohl X als auch Y = both X and Y (formal — connects nouns, phrases, clauses)","explanation":"Sowohl...als auch = both...and (formal, written German). More emphatic than und (and). Sowohl Vorteile als auch Nachteile = both advantages and disadvantages. Sowohl die Regierung als auch die Opposition = both the government and the opposition. The verb agrees with both subjects (plural if different). Contrast: entweder...oder (either...or), weder...noch (neither...nor).","examples":[{"sentence":"Sowohl Arbeitgeber als auch Arbeitnehmer profitieren von stabilen Tarifverträgen.","translation":"Both employers and employees benefit from stable collective agreements."},{"sentence":"Das Projekt ist sowohl innovativ als auch kostengünstig.","translation":"The project is both innovative and cost-effective."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Teilhabe'' means?","options":["participation/inclusion","sharing","taking part","involvement"],"correctAnswer":"participation/inclusion"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Successful integration requires efforts from both the receiving society and those who have immigrated.","options":["Gelingende Integration erfordert Anstrengungen sowohl von Seiten der Aufnahmegesellschaft als auch der Zugewanderten.","Integration braucht Arbeit von beiden Seiten.","Sowohl die Gesellschaft als auch Migranten müssen sich bemühen.","Gute Integration erfordert viel Aufwand."],"correctAnswer":"Gelingende Integration erfordert Anstrengungen sowohl von Seiten der Aufnahmegesellschaft als auch der Zugewanderten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Sowohl Arbeitgeber ___ Arbeitnehmer profitieren.","options":["als auch","und auch","wie auch","sowie auch"],"correctAnswer":"als auch"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The project is both innovative and cost-effective","wordBankItems":["Das","Projekt","ist","sowohl","innovativ","als","auch","kostengünstig","."],"correctAnswer":"Das Projekt ist sowohl innovativ als auch kostengünstig ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Weder...noch'' means?","options":["neither...nor","either...or","both...and","not only...but also"],"correctAnswer":"neither...nor"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000184',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss poverty and wealth at B2","Use Armut und Reichtum vocabulary","Talk about economic inequality"],"explanation":{"intro":"Poverty and wealth vocabulary at B2 covers economic inequality, poverty lines, and redistribution debates.","culturalNote":"Relative Einkommensarmut (relative income poverty) in Germany: officially measured as below 60% of median income. Germany has growing Reichtumskonzentration (concentration of wealth) — top 10% own ~60% of wealth. Tafelläden (charity food banks) serve over 2 million people. Soziale Durchlässigkeit (social mobility) is relatively low. Chancenungleichheit (unequal opportunity) is a core political issue."},"examples":[{"german":"Trotz wirtschaftlichem Wohlstand hat Deutschland ein erhebliches Problem mit relativer Einkommensarmut.","english":"Despite economic prosperity, Germany has a considerable problem with relative income poverty."},{"german":"Die soziale Durchlässigkeit ist in Deutschland im internationalen Vergleich gering.","english":"Social mobility is low in Germany by international comparison."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss poverty, wealth inequality, and social mobility in Germany at B2."}}',
'{"items":[{"word":"die Einkommensarmut","translation":"income poverty","pronunciation":"dee YN-kom-ens-ar-moot","example":"Relative Einkommensarmut."},{"word":"die Durchlässigkeit","translation":"mobility/permeability","pronunciation":"dee DOORH-läs-ikh-kyt","example":"Soziale Durchlässigkeit."},{"word":"die Chancenungleichheit","translation":"unequal opportunity","pronunciation":"dee SHAN-tsen-oon-glykh-hyt","example":"Chancenungleichheit."},{"word":"die Konzentration","translation":"concentration","pronunciation":"dee kon-tsen-trah-tsee-OHN","example":"Reichtumskonzentration."},{"word":"gering","translation":"low/small","pronunciation":"geh-RING","example":"Gering einschätzen."},{"word":"im internationalen Vergleich","translation":"by international comparison","pronunciation":"im in-ter-na-tsyoh-NAH-len fer-GLYKH","example":"Im internationalen Vergleich."}]}',
'{"title":"Im Vergleich / Im internationalen Vergleich — by comparison","pattern":"im Vergleich zu + dative (compared to) OR im internationalen Vergleich (by international comparison) — formal comparative framing","explanation":"Im Vergleich zu + dative = compared to. Im internationalen Vergleich = by international comparison (standalone adverb phrase — no zu needed). Im europäischen Vergleich = by European comparison. These phrases frame a fact as relative, not absolute. Vergleichen mit (to compare with): Verglichen mit Deutschland... = Compared to Germany... Also: im Gegensatz zu (in contrast to — more adversarial).","examples":[{"sentence":"Im Vergleich zum Vorjahr sind die Kosten gesunken.","translation":"Compared to the previous year, costs have fallen."},{"sentence":"Im europäischen Vergleich hat Deutschland eine relativ niedrige Inflation.","translation":"By European comparison, Germany has a relatively low inflation rate."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Durchlässigkeit'' means in a social context?","options":["mobility/permeability","openness","access","flexibility"],"correctAnswer":"mobility/permeability"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Social mobility is low in Germany by international comparison.","options":["Die soziale Durchlässigkeit ist in Deutschland im internationalen Vergleich gering.","Deutschland hat geringe soziale Mobilität.","Im internationalen Vergleich ist Deutschland gering.","Soziale Durchlässigkeit ist ein Problem in Deutschland."],"correctAnswer":"Die soziale Durchlässigkeit ist in Deutschland im internationalen Vergleich gering."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Im Vergleich zum Vorjahr sind die Kosten ___.","options":["gesunken","gefallen","kleiner","niedriger"],"correctAnswer":"gesunken"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: By European comparison, Germany has a relatively low inflation rate","wordBankItems":["Im","europäischen","Vergleich","hat","Deutschland","eine","relativ","niedrige","Inflation","."],"correctAnswer":"Im europäischen Vergleich hat Deutschland eine relativ niedrige Inflation ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Gering'' means?","options":["low/small","slight","modest","minor"],"correctAnswer":"low/small"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000185',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss social inequality at B2","Use soziale Ungleichheit vocabulary","Analyse structural causes"],"explanation":{"intro":"Social inequality vocabulary at B2 covers structural causes, opportunity gaps, and policy responses.","culturalNote":"Soziale Ungleichheit in Germany is analysed through multiple lenses: income inequality (Gini-Koeffizient), wealth inequality, educational inequality, and health inequality. Key concept: Matthäus-Effekt (Matthew Effect — advantage compounds advantage). Pierre Bourdieu''s Kapitalformen (social, cultural, economic capital) are well-known in German sociology."},"examples":[{"german":"Strukturelle Ungleichheit entsteht nicht zufällig, sondern durch systematische Benachteiligung bestimmter Gruppen.","english":"Structural inequality does not arise by chance but through the systematic disadvantaging of certain groups."},{"german":"Bildung gilt als einer der wichtigsten Hebel, um soziale Ungleichheit langfristig zu reduzieren.","english":"Education is regarded as one of the most important levers for reducing social inequality in the long term."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss structural causes of social inequality and policy responses at B2."}}',
'{"items":[{"word":"strukturell","translation":"structural","pronunciation":"shtrook-tuh-REL","example":"Strukturelle Ursachen."},{"word":"die Benachteiligung","translation":"disadvantaging/discrimination","pronunciation":"dee beh-NAKH-ty-lee-goong","example":"Systematische Benachteiligung."},{"word":"zufällig","translation":"by chance/accidental","pronunciation":"TSOO-fäl-ikh","example":"Nicht zufällig."},{"word":"der Hebel","translation":"lever","pronunciation":"dayr HAY-bel","example":"Ein wichtiger Hebel."},{"word":"reduzieren","translation":"to reduce","pronunciation":"reh-doo-TSEER-en","example":"Ungleichheit reduzieren."},{"word":"systematisch","translation":"systematic","pronunciation":"züs-teh-MAH-tish","example":"Systematisch vorgehen."}]}',
'{"title":"Nicht...sondern — not...but rather (corrective contrast)","pattern":"nicht X, sondern Y = not X, but (rather) Y (correction or strong contrast)","explanation":"Nicht...sondern = not...but rather. It corrects a previous claim or expectation: Die Ursache ist nicht Pech, sondern Struktur = The cause is not bad luck, but structure. Stronger than aber (but): sondern is specifically for contradicting what was negated. Rule: nicht + [negated element], sondern + [correct element]. The contrast is exclusive: one is right, the other wrong.","examples":[{"sentence":"Das war nicht meine Idee, sondern die Idee meines Kollegen.","translation":"That was not my idea but my colleague''s idea."},{"sentence":"Nicht die Technik, sondern der Mensch ist entscheidend.","translation":"Not technology but the human being is decisive."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Strukturell'' means?","options":["structural","foundational","systematic","institutional"],"correctAnswer":"structural"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Structural inequality does not arise by chance but through the systematic disadvantaging of certain groups.","options":["Strukturelle Ungleichheit entsteht nicht zufällig, sondern durch systematische Benachteiligung bestimmter Gruppen.","Ungleichheit ist nicht Zufall, sondern System.","Bestimmte Gruppen werden systematisch benachteiligt.","Strukturelle Ungleichheit hat systematische Ursachen."],"correctAnswer":"Strukturelle Ungleichheit entsteht nicht zufällig, sondern durch systematische Benachteiligung bestimmter Gruppen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das war nicht meine Idee, ___ die Idee meines Kollegen.","options":["sondern","aber","jedoch","stattdessen"],"correctAnswer":"sondern"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Not technology but the human being is decisive","wordBankItems":["Nicht","die","Technik",",","sondern","der","Mensch","ist","entscheidend","."],"correctAnswer":"Nicht die Technik , sondern der Mensch ist entscheidend ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Nicht...sondern'' is used to?","options":["correct/contradict what was negated","add information","contrast two equal options","concede a point"],"correctAnswer":"correct/contradict what was negated"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000186',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss justice at B2","Use Gerechtigkeit vocabulary","Talk about distributive and procedural justice"],"explanation":{"intro":"Justice vocabulary at B2 covers social, distributive, procedural, and restorative justice concepts.","culturalNote":"Gerechtigkeit is a core value in German political culture. Key distinctions: Verteilungsgerechtigkeit (distributive justice — fair distribution of resources), Verfahrensgerechtigkeit (procedural justice — fair processes), Chancengerechtigkeit (equality of opportunity), Geschlechtergerechtigkeit (gender justice). The Federal Constitutional Court (Bundesverfassungsgericht) is seen as the ultimate guardian of justice."},"examples":[{"german":"Verteilungsgerechtigkeit bedeutet nicht Gleichheit des Ergebnisses, sondern faire Rahmenbedingungen.","english":"Distributive justice does not mean equality of outcome but fair framework conditions."},{"german":"Ohne funktionierende Institutionen lässt sich soziale Gerechtigkeit nicht dauerhaft verwirklichen.","english":"Without functioning institutions, social justice cannot be permanently realised."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss concepts of justice, fairness, and institutional guarantees at B2."}}',
'{"items":[{"word":"die Verteilungsgerechtigkeit","translation":"distributive justice","pronunciation":"dee fer-TY-loonks-geh-rekh-tikh-kyt","example":"Verteilungsgerechtigkeit."},{"word":"die Rahmenbedingung","translation":"framework condition","pronunciation":"dee RAH-men-beh-ding-oong","example":"Faire Rahmenbedingungen."},{"word":"dauerhaft","translation":"permanently/durably","pronunciation":"DOW-er-haft","example":"Dauerhaft lösen."},{"word":"verwirklichen","translation":"to realise/implement","pronunciation":"fer-VIR-klikh-en","example":"Gerechtigkeit verwirklichen."},{"word":"die Institution","translation":"institution","pronunciation":"dee in-sti-too-tsee-OHN","example":"Funktionierende Institutionen."},{"word":"funktionieren","translation":"to function/work","pronunciation":"fonk-tsyoh-NEER-en","example":"Funktionieren."}]}',
'{"title":"Sich verwirklichen / etwas verwirklichen — to be realised / to realise","pattern":"etwas verwirklichen (to realise/implement) OR sich verwirklichen (to fulfil oneself/be realised)","explanation":"Verwirklichen = to realise, implement, fulfil. Transitive: Ziele verwirklichen = to realise goals. Passive: Gerechtigkeit kann nicht verwirklichen werden = Justice cannot be realised. Reflexive: sich verwirklichen = to fulfil oneself, to materialise. Die Verwirklichung = realisation, implementation. Synonym: umsetzen (to implement — more practical/concrete), realisieren (to realise — more technical/project language).","examples":[{"sentence":"Der Traum hat sich verwirklicht.","translation":"The dream has been realised/come true."},{"sentence":"Es ist schwierig, diese Ideen in der Praxis zu verwirklichen.","translation":"It is difficult to realise these ideas in practice."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Rahmenbedingung'' means?","options":["framework condition","framework","condition","framework agreement"],"correctAnswer":"framework condition"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Distributive justice does not mean equality of outcome but fair framework conditions.","options":["Verteilungsgerechtigkeit bedeutet nicht Gleichheit des Ergebnisses, sondern faire Rahmenbedingungen.","Gerechtigkeit bedeutet gleiche Ergebnisse.","Faire Bedingungen sind wichtiger als gleiche Ergebnisse.","Verteilungsgerechtigkeit meint faire Verteilung."],"correctAnswer":"Verteilungsgerechtigkeit bedeutet nicht Gleichheit des Ergebnisses, sondern faire Rahmenbedingungen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Traum hat sich ___.","options":["verwirklicht","verwirklichen","zu verwirklichen","verwirklicht haben"],"correctAnswer":"verwirklicht"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: It is difficult to realise these ideas in practice","wordBankItems":["Es","ist","schwierig",",","diese","Ideen","in","der","Praxis","zu","verwirklichen","."],"correctAnswer":"Es ist schwierig , diese Ideen in der Praxis zu verwirklichen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Dauerhaft'' means?","options":["permanently/durably","long-lasting","sustainable","perpetual"],"correctAnswer":"permanently/durably"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000187',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss human rights at B2","Use Menschenrechte vocabulary","Talk about international human rights frameworks"],"explanation":{"intro":"Human rights vocabulary at B2 covers fundamental rights, international law, and human rights protection.","culturalNote":"Germany''s Grundgesetz (Basic Law) is a human-rights-first constitution shaped by the experience of National Socialism. Article 1: Die Würde des Menschen ist unantastbar (Human dignity is inviolable). Germany is a leading supporter of the UN human rights system and International Criminal Court. Amnesty International and Human Rights Watch have significant German offices."},"examples":[{"german":"Die Menschenwürde bildet das Fundament des deutschen Grundgesetzes und ist unantastbar.","english":"Human dignity forms the foundation of the German Basic Law and is inviolable."},{"german":"Der Schutz von Minderheiten gehört zu den Kernprinzipien des internationalen Menschenrechts.","english":"The protection of minorities is one of the core principles of international human rights."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss human rights, constitutional rights, and international human rights law at B2."}}',
'{"items":[{"word":"die Menschenwürde","translation":"human dignity","pronunciation":"dee MEN-shen-vür-deh","example":"Menschenwürde schützen."},{"word":"unantastbar","translation":"inviolable/untouchable","pronunciation":"OON-an-tast-bar","example":"Unantastbar."},{"word":"das Kernprinzip","translation":"core principle","pronunciation":"dahs KERN-prin-tsip","example":"Kernprinzip."},{"word":"das Fundament","translation":"foundation/basis","pronunciation":"dahs foon-dah-MENT","example":"Das Fundament bilden."},{"word":"der Schutz","translation":"protection","pronunciation":"dayr shoots","example":"Schutz von Minderheiten."},{"word":"die Minderheit","translation":"minority","pronunciation":"dee MIN-der-hyt","example":"Nationale Minderheiten."}]}',
'{"title":"Bilden — to form/constitute (formal)","pattern":"etwas bildet + noun = something forms, constitutes, makes up (formal academic/legal language)","explanation":"Bilden in the sense of forming/constituting: Die Grundrechte bilden das Fundament = The fundamental rights form the foundation. Useful in formal writing as a more elevated alternative to sein (to be) or darstellen (to represent/constitute). Die Ausnahme bildet = the exception is... Den Kern bilden = to form the core. Also: eine Gruppe bilden (to form a group), sich bilden (to educate oneself), gebildet sein (to be educated).","examples":[{"sentence":"Vertrauen bildet die Grundlage jeder guten Zusammenarbeit.","translation":"Trust forms the basis of all good cooperation."},{"sentence":"Diese Regel bildet eine wichtige Ausnahme.","translation":"This rule constitutes an important exception."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Unantastbar'' means?","options":["inviolable/untouchable","unreachable","protected","absolute"],"correctAnswer":"inviolable/untouchable"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Human dignity forms the foundation of the German Basic Law and is inviolable.","options":["Die Menschenwürde bildet das Fundament des deutschen Grundgesetzes und ist unantastbar.","Das Grundgesetz schützt die Menschenwürde.","Die Menschenwürde ist das Wichtigste im Grundgesetz.","Das deutsche Grundgesetz garantiert Menschenwürde."],"correctAnswer":"Die Menschenwürde bildet das Fundament des deutschen Grundgesetzes und ist unantastbar."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Vertrauen bildet die ___ jeder guten Zusammenarbeit.","options":["Grundlage","Basis","Fundament","Voraussetzung"],"correctAnswer":"Grundlage"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: This rule constitutes an important exception","wordBankItems":["Diese","Regel","bildet","eine","wichtige","Ausnahme","."],"correctAnswer":"Diese Regel bildet eine wichtige Ausnahme ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das Kernprinzip'' means?","options":["core principle","key principle","main principle","central principle"],"correctAnswer":"core principle"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000188',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss civil rights at B2","Use Bürgerrechte vocabulary","Talk about rights, freedoms, and their limits"],"explanation":{"intro":"Civil rights vocabulary at B2 covers fundamental freedoms, their limits, and the balance between liberty and security.","culturalNote":"The Grundgesetz guarantees civil liberties (Grundrechte) that cannot be removed (Wesengehalt — essential core). Key rights: Meinungsfreiheit (free speech), Versammlungsfreiheit (freedom of assembly), Informationsfreiheit (freedom of information). Courts balance rights: Verhältnismäßigkeit (proportionality) is a key constitutional principle. Rights can be restricted but only proportionally."},"examples":[{"german":"Grundrechte sind nicht schrankenlos — sie können durch Gesetz eingeschränkt werden, aber nur verhältnismäßig.","english":"Fundamental rights are not unlimited — they can be restricted by law, but only proportionately."},{"german":"Das Bundesverfassungsgericht wacht darüber, dass Einschränkungen verhältnismäßig bleiben.","english":"The Federal Constitutional Court watches over whether restrictions remain proportionate."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss civil rights, constitutional limits, and proportionality at B2."}}',
'{"items":[{"word":"schrankenlos","translation":"unlimited/without limits","pronunciation":"SHRANK-en-lohs","example":"Schrankenlos."},{"word":"verhältnismäßig","translation":"proportionate/proportional","pronunciation":"fer-HÄL-tnis-mä-sikh","example":"Verhältnismäßig einschränken."},{"word":"wachen über","translation":"to watch over/guard","pronunciation":"VAKH-en ü-ber","example":"Wacht darüber."},{"word":"das Grundrecht","translation":"fundamental right","pronunciation":"dahs GROONT-rekht","example":"Grundrechte."},{"word":"die Versammlungsfreiheit","translation":"freedom of assembly","pronunciation":"dee fer-ZAM-loonks-fry-hyt","example":"Versammlungsfreiheit."},{"word":"der Wesensgehalt","translation":"essential core (of a right)","pronunciation":"dayr VAY-zens-geh-halt","example":"Wesensgehalt."}]}',
'{"title":"Darüber wachen / wachen darüber — to watch over (pronominal adverb)","pattern":"wachen über + accusative (or darüber) + dass-clause = to watch over whether/that","explanation":"Wachen über = to guard, watch over. Takes accusative or darüber dass-clause. Das Gericht wacht darüber, dass die Rechte gewahrt werden = The court watches over whether rights are respected. Darüber = über + das (pronominal adverb combining preposition with demonstrative, obligatory when the object is a clause). Pattern: wachen darüber, dass + V-final clause.","examples":[{"sentence":"Die Behörde wacht darüber, dass die Vorschriften eingehalten werden.","translation":"The authority watches over whether the regulations are adhered to."},{"sentence":"Eltern wachen darüber, dass ihre Kinder sicher sind.","translation":"Parents watch over whether their children are safe."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Verhältnismäßig'' means?","options":["proportionate/proportional","relative","measured","reasonable"],"correctAnswer":"proportionate/proportional"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Fundamental rights are not unlimited — they can be restricted by law, but only proportionately.","options":["Grundrechte sind nicht schrankenlos — sie können durch Gesetz eingeschränkt werden, aber nur verhältnismäßig.","Grundrechte gelten immer, können aber eingeschränkt werden.","Rechte können eingeschränkt werden, aber nicht unbegrenzt.","Das Gesetz schränkt Grundrechte proportional ein."],"correctAnswer":"Grundrechte sind nicht schrankenlos — sie können durch Gesetz eingeschränkt werden, aber nur verhältnismäßig."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Behörde wacht darüber, dass die Vorschriften eingehalten ___.","options":["werden","sind","sein werden","werden müssen"],"correctAnswer":"werden"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Parents watch over whether their children are safe","wordBankItems":["Eltern","wachen","darüber",",","dass","ihre","Kinder","sicher","sind","."],"correctAnswer":"Eltern wachen darüber , dass ihre Kinder sicher sind ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Schrankenlos'' means?","options":["unlimited/without limits","without barriers","borderless","unregulated"],"correctAnswer":"unlimited/without limits"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000189',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss discrimination at B2","Use Diskriminierung vocabulary","Talk about anti-discrimination law and experience"],"explanation":{"intro":"Discrimination vocabulary at B2 covers forms of discrimination, anti-discrimination law, and intersectionality.","culturalNote":"Germany''s Allgemeines Gleichbehandlungsgesetz (AGG — General Equal Treatment Act, 2006) prohibits discrimination based on race, ethnic origin, gender, religion, disability, age, and sexual orientation. The Antidiskriminierungsstelle des Bundes (Federal Anti-Discrimination Agency) provides support. Intersektionalität (intersectionality) is increasingly used in public discourse."},"examples":[{"german":"Das Allgemeine Gleichbehandlungsgesetz schützt Menschen vor Diskriminierung aufgrund verschiedener Merkmale.","english":"The General Equal Treatment Act protects people from discrimination on the basis of various characteristics."},{"german":"Mittelbare Diskriminierung liegt vor, wenn scheinbar neutrale Regelungen bestimmte Gruppen unverhältnismäßig benachteiligen.","english":"Indirect discrimination occurs when seemingly neutral regulations disproportionately disadvantage certain groups."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss discrimination, anti-discrimination law, and equality at B2."}}',
'{"items":[{"word":"die mittelbare Diskriminierung","translation":"indirect discrimination","pronunciation":"dee MITtel-ba-reh dis-kri-mi-NEER-oong","example":"Mittelbare Diskriminierung."},{"word":"scheinbar","translation":"seemingly/apparently","pronunciation":"SHYN-bar","example":"Scheinbar neutral."},{"word":"unverhältnismäßig","translation":"disproportionate","pronunciation":"OON-fer-häl-tnis-mä-sikh","example":"Unverhältnismäßig benachteiligen."},{"word":"das Merkmal","translation":"characteristic/feature","pronunciation":"dahs MERK-mahl","example":"Bestimmte Merkmale."},{"word":"das Gleichbehandlungsgesetz","translation":"equal treatment act","pronunciation":"dahs GLYKH-beh-hand-loonks-geh-zets","example":"AGG."},{"word":"vorliegen","translation":"to be present/to exist (formally)","pronunciation":"FOR-lee-gen","example":"Liegt vor."}]}',
'{"title":"Vorliegen — to be present/to exist (formally)","pattern":"etwas liegt vor = something exists/is present/has occurred (formal, legal, bureaucratic usage)","explanation":"Vorliegen = to be present, to exist, to be at hand (formal). Used in legal, official, and academic contexts: Ein Fehler liegt vor = An error has occurred/is present. Diskriminierung liegt vor, wenn... = Discrimination occurs when... Die Voraussetzungen liegen vor = The conditions are met/present. Also: Wenn keine Genehmigung vorliegt = if no approval is on file. Vorliegende Informationen = available information.","examples":[{"sentence":"Wenn kein Vertrag vorliegt, gilt das Gesetz.","translation":"When no contract is on file/exists, the law applies."},{"sentence":"Es liegen keine Beweise vor.","translation":"No evidence exists/is on file."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Scheinbar'' means?","options":["seemingly/apparently","clearly","obviously","evidently"],"correctAnswer":"seemingly/apparently"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Indirect discrimination occurs when seemingly neutral regulations disproportionately disadvantage certain groups.","options":["Mittelbare Diskriminierung liegt vor, wenn scheinbar neutrale Regelungen bestimmte Gruppen unverhältnismäßig benachteiligen.","Diskriminierung ist mittelbar, wenn sie durch neutrale Regeln entsteht.","Neutrale Regeln können Diskriminierung verursachen.","Bestimmte Gruppen werden durch Regelungen benachteiligt."],"correctAnswer":"Mittelbare Diskriminierung liegt vor, wenn scheinbar neutrale Regelungen bestimmte Gruppen unverhältnismäßig benachteiligen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Wenn kein Vertrag vorliegt, ___ das Gesetz.","options":["gilt","gelte","geltet","gegolten"],"correctAnswer":"gilt"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: No evidence exists/is on file","wordBankItems":["Es","liegen","keine","Beweise","vor","."],"correctAnswer":"Es liegen keine Beweise vor ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das Merkmal'' means?","options":["characteristic/feature","mark","sign","indicator"],"correctAnswer":"characteristic/feature"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000018a',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss gender equality at B2","Use Gleichstellung vocabulary","Talk about gender pay gap and workplace equality"],"explanation":{"intro":"Gender equality vocabulary at B2 covers the pay gap, political representation, and equality legislation.","culturalNote":"Germany''s Gender Pay Gap is around 18% (unadjusted) — among the highest in the EU. Frauenquote (gender quota) debate: DAX companies now have a 30% supervisory board quota. Parental leave (Elterngeld) is available to all genders. Key concepts: geschlechterspezifische Stereotypen (gender-specific stereotypes), Gläserne Decke (glass ceiling), Vereinbarkeit von Familie und Beruf (work-life balance — literally compatibility of family and career)."},"examples":[{"german":"Trotz formaler Gleichstellung bestehen in der Praxis erhebliche Unterschiede zwischen Männern und Frauen.","english":"Despite formal equality, considerable differences between men and women persist in practice."},{"german":"Die Vereinbarkeit von Familie und Beruf bleibt eine Herausforderung, die alle Geschlechter betrifft.","english":"Work-life balance remains a challenge that affects all genders."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss gender equality, pay gap, and work-life balance vocabulary at B2."}}',
'{"items":[{"word":"die Gleichstellung","translation":"equality (formal)","pronunciation":"dee GLYKH-shtel-oong","example":"Gleichstellung."},{"word":"formell","translation":"formal/official","pronunciation":"for-MEL","example":"Formelle Gleichstellung."},{"word":"die Vereinbarkeit","translation":"compatibility/work-life balance","pronunciation":"dee fer-YN-bar-kyt","example":"Vereinbarkeit von Familie und Beruf."},{"word":"die Gläserne Decke","translation":"glass ceiling","pronunciation":"dee GLAY-zer-neh DEK-eh","example":"Gläserne Decke."},{"word":"betreffen","translation":"to affect/concern","pronunciation":"beh-TREF-en","example":"Alle betreffen."},{"word":"die Frauenquote","translation":"gender quota (for women)","pronunciation":"dee FROW-en-kwoh-teh","example":"Frauenquote."}]}',
'{"title":"Bestehen — to persist/exist (of situations)","pattern":"etwas besteht (still exists, persists — of conditions, differences, problems)","explanation":"Bestehen (to exist, persist — of abstract things) = to remain in place. Unterschiede bestehen = differences exist/persist. Die Herausforderung besteht darin, dass... = The challenge lies in the fact that... Woraus besteht...? = What does it consist of? Compare: bleiben (to remain — broader), fortbestehen (to continue to exist — more emphatic persistence), weiter bestehen (to continue existing).","examples":[{"sentence":"Diese Unterschiede bestehen trotz jahrzehntelanger Bemühungen weiterhin.","translation":"These differences persist despite decades of efforts."},{"sentence":"Das Problem besteht darin, dass viele Maßnahmen nicht umgesetzt werden.","translation":"The problem lies in the fact that many measures are not implemented."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Vereinbarkeit'' in ''Vereinbarkeit von Familie und Beruf'' means?","options":["compatibility/work-life balance","combination","balance","reconciliation"],"correctAnswer":"compatibility/work-life balance"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Despite formal equality, considerable differences between men and women persist in practice.","options":["Trotz formaler Gleichstellung bestehen in der Praxis erhebliche Unterschiede zwischen Männern und Frauen.","Frauen und Männer sind formal gleich, aber nicht in der Praxis.","Formale Gleichstellung bedeutet keine echte Gleichheit.","Unterschiede zwischen Männern und Frauen existieren trotz Gleichstellung."],"correctAnswer":"Trotz formaler Gleichstellung bestehen in der Praxis erhebliche Unterschiede zwischen Männern und Frauen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Diese Unterschiede bestehen trotz jahrzehntelanger Bemühungen ___.","options":["weiterhin","weiter","noch","immer"],"correctAnswer":"weiterhin"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The problem lies in the fact that many measures are not implemented","wordBankItems":["Das","Problem","besteht","darin",",","dass","viele","Maßnahmen","nicht","umgesetzt","werden","."],"correctAnswer":"Das Problem besteht darin , dass viele Maßnahmen nicht umgesetzt werden ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Gläserne Decke'' means?","options":["glass ceiling","glass wall","transparent barrier","invisible ceiling"],"correctAnswer":"glass ceiling"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000018b',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss diversity at B2","Use Diversität vocabulary","Talk about inclusion and representation"],"explanation":{"intro":"Diversity vocabulary at B2 covers inclusion, representation, intersectionality, and diversity management.","culturalNote":"Diversität and Vielfalt (diversity) are increasingly prominent in German discourse. Diversity-Management is standard in large German companies. Inklusion (inclusion — especially for people with disabilities) is a constitutional and educational mandate. Cultural diversity: Germany has 83+ nationalities with significant community. The concept Behinderung (disability) is framed through Behinderung als gesellschaftliche Barriere (disability as social barrier) rather than purely medical model."},"examples":[{"german":"Vielfalt ist eine Stärke — diverse Teams entwickeln nachweislich kreativere Lösungen.","english":"Diversity is a strength — diverse teams demonstrably develop more creative solutions."},{"german":"Echte Inklusion geht über bloße Toleranz hinaus und setzt aktive Teilhabe voraus.","english":"True inclusion goes beyond mere tolerance and presupposes active participation."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss diversity, inclusion, and representation at B2."}}',
'{"items":[{"word":"die Vielfalt","translation":"diversity/variety","pronunciation":"dee FEEL-falt","example":"Kulturelle Vielfalt."},{"word":"nachweislich","translation":"demonstrably/provably","pronunciation":"NAKH-vys-likh","example":"Nachweislich besser."},{"word":"die Inklusion","translation":"inclusion","pronunciation":"dee in-kloo-TSYOH-n","example":"Inklusion."},{"word":"bloß","translation":"mere/merely/only","pronunciation":"blohs","example":"Bloße Toleranz."},{"word":"voraussetzen","translation":"to presuppose/require","pronunciation":"for-OWS-zet-zen","example":"Etwas voraussetzen."},{"word":"hinausgehen über","translation":"to go beyond","pronunciation":"hin-OWS-gay-en ü-ber","example":"Hinausgehen über."}]}',
'{"title":"Über etwas hinausgehen — to go beyond something","pattern":"über + accusative hinausgehen (separable — to go beyond, exceed, transcend)","explanation":"Hinausgehen über + accusative = to go beyond, exceed. Echte Inklusion geht über Toleranz hinaus = True inclusion goes beyond tolerance. Perfect: ist hinausgegangen. The separable pattern: geht... hinaus. Also: darüber hinausgehen (go beyond that). Compare: überschreiten (to exceed/cross — often a limit), übersteigen (to exceed — often a number/amount), hinauswachsen über (to grow beyond).","examples":[{"sentence":"Das Projekt geht weit über unsere ursprünglichen Erwartungen hinaus.","translation":"The project far exceeds our original expectations."},{"sentence":"Sein Einfluss geht über nationale Grenzen hinaus.","translation":"His influence goes beyond national borders."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Nachweislich'' means?","options":["demonstrably/provably","clearly","evidently","measurably"],"correctAnswer":"demonstrably/provably"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"True inclusion goes beyond mere tolerance and presupposes active participation.","options":["Echte Inklusion geht über bloße Toleranz hinaus und setzt aktive Teilhabe voraus.","Inklusion ist mehr als Toleranz.","Aktive Teilhabe ist wichtiger als Toleranz.","Inklusion setzt Toleranz und Teilhabe voraus."],"correctAnswer":"Echte Inklusion geht über bloße Toleranz hinaus und setzt aktive Teilhabe voraus."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Projekt geht weit über unsere ursprünglichen Erwartungen ___.","options":["hinaus","hinüber","heraus","beyond"],"correctAnswer":"hinaus"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: His influence goes beyond national borders","wordBankItems":["Sein","Einfluss","geht","über","nationale","Grenzen","hinaus","."],"correctAnswer":"Sein Einfluss geht über nationale Grenzen hinaus ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Voraussetzen'' means?","options":["to presuppose/require","to assume","to precondition","to foresee"],"correctAnswer":"to presuppose/require"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000018c',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss German history at B2","Use German history vocabulary","Talk about key historical periods"],"explanation":{"intro":"German history vocabulary at B2 covers key periods from the Weimar Republic to unified Germany.","culturalNote":"Key periods of German history: Weimarer Republik (1919-1933 — first German democracy), Nationalsozialismus (1933-1945 — contextual historical education, Aufarbeitung), Nachkriegszeit (post-war era 1945-1955), Wirtschaftswunder (Economic Miracle 1955-1970), Deutsche Teilung (division, 1945-1990), Wiedervereinigung (reunification 1990). German historical education emphasises Erinnerungskultur (memorial culture) and Verantwortung (responsibility)."},"examples":[{"german":"Die Aufarbeitung der nationalsozialistischen Vergangenheit ist in Deutschland ein zentrales Element der Erinnerungskultur.","english":"Coming to terms with the National Socialist past is a central element of memorial culture in Germany."},{"german":"Das Wirtschaftswunder verwandelte Westdeutschland innerhalb weniger Jahrzehnte in eine der größten Volkswirtschaften der Welt.","english":"The Economic Miracle transformed West Germany within a few decades into one of the world''s largest economies."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss German historical periods, vocabulary, and memorial culture at B2."}}',
'{"items":[{"word":"die Aufarbeitung","translation":"coming to terms with/processing (historically)","pronunciation":"dee OWF-ar-by-toong","example":"Aufarbeitung."},{"word":"das Wirtschaftswunder","translation":"economic miracle","pronunciation":"dahs VIRT-shafts-voon-der","example":"Wirtschaftswunder."},{"word":"verwandeln","translation":"to transform","pronunciation":"fer-VAN-deln","example":"In etwas verwandeln."},{"word":"die Volkswirtschaft","translation":"national economy","pronunciation":"dee FOLKS-virt-shaft","example":"Größte Volkswirtschaft."},{"word":"innerhalb","translation":"within","pronunciation":"IN-er-halp","example":"Innerhalb weniger Jahre."},{"word":"die Erinnerungskultur","translation":"memorial culture","pronunciation":"dee eh-RIN-eh-roonks-kool-toor","example":"Erinnerungskultur."}]}',
'{"title":"Verwandeln in — to transform into","pattern":"etwas verwandeln in + accusative = to transform something into something else","explanation":"Verwandeln in + accusative = to transform into. Das Wirtschaftswunder verwandelte Deutschland in eine Industriemacht = The Economic Miracle transformed Germany into an industrial power. Reflexive: sich in etwas verwandeln = to turn into, be transformed into. Perfect: hat verwandelt. Compare: umwandeln (to convert/transform — technical/physical change), verändern (to change — less complete), umgestalten (to reshape/redesign).","examples":[{"sentence":"Das Zentrum wurde in ein Kulturzentrum verwandelt.","translation":"The centre was transformed into a cultural centre."},{"sentence":"Er hat seine Erfahrungen in Kunst verwandelt.","translation":"He has transformed his experiences into art."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Aufarbeitung'' in historical context means?","options":["coming to terms with/processing","working through","historical work","analysis"],"correctAnswer":"coming to terms with/processing"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The Economic Miracle transformed West Germany within a few decades into one of the world''s largest economies.","options":["Das Wirtschaftswunder verwandelte Westdeutschland innerhalb weniger Jahrzehnte in eine der größten Volkswirtschaften der Welt.","Das Wirtschaftswunder hat Westdeutschland sehr verändert.","Westdeutschland wurde durch das Wirtschaftswunder reich.","Das Wirtschaftswunder machte Deutschland groß."],"correctAnswer":"Das Wirtschaftswunder verwandelte Westdeutschland innerhalb weniger Jahrzehnte in eine der größten Volkswirtschaften der Welt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Zentrum wurde in ein Kulturzentrum ___.","options":["verwandelt","verwandeln","verwandelnd","umgewandelt"],"correctAnswer":"verwandelt"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He has transformed his experiences into art","wordBankItems":["Er","hat","seine","Erfahrungen","in","Kunst","verwandelt","."],"correctAnswer":"Er hat seine Erfahrungen in Kunst verwandelt ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Volkswirtschaft'' means?","options":["national economy","people''s economy","folk economy","general economy"],"correctAnswer":"national economy"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000018d',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss German reunification at B2","Use Wiedervereinigung vocabulary","Analyse impact and legacy"],"explanation":{"intro":"Reunification vocabulary at B2 covers the fall of the Wall, the reunification process, and its ongoing legacy.","culturalNote":"Die Wiedervereinigung (German reunification) occurred on 3 October 1990 (Tag der Deutschen Einheit — national holiday). The Währungsunion (currency union) preceded it in July 1990. Key challenges: Aufbau Ost (reconstruction of eastern Germany), Mauer im Kopf (mental wall — persisting inner divisions), Treuhandanstalt (trust agency — privatised 8,000 East German companies), unemployment, and migration westward."},"examples":[{"german":"Die Wiedervereinigung war ein historisches Ereignis, das tiefgreifende wirtschaftliche und gesellschaftliche Veränderungen mit sich brachte.","english":"Reunification was a historic event that brought with it profound economic and social changes."},{"german":"Die Mauer im Kopf beschreibt die anhaltenden mentalen Unterschiede zwischen Ost- und Westdeutschen.","english":"The wall in the mind describes the ongoing mental differences between east and west Germans."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss German reunification, its process, challenges, and legacy at B2."}}',
'{"items":[{"word":"tiefgreifend","translation":"profound/deep-reaching","pronunciation":"TEEF-gry-fend","example":"Tiefgreifende Veränderungen."},{"word":"mit sich bringen","translation":"to bring with it/entail","pronunciation":"mit zikh BRING-en","example":"Veränderungen mit sich bringen."},{"word":"anhaltend","translation":"ongoing/continuing","pronunciation":"AN-hal-tend","example":"Anhaltende Unterschiede."},{"word":"der Aufbau Ost","translation":"reconstruction of eastern Germany","pronunciation":"dayr OWF-bow ost","example":"Aufbau Ost."},{"word":"die Währungsunion","translation":"currency union","pronunciation":"dee VÄ-roonks-oo-nee-OHN","example":"Währungsunion."},{"word":"das Ereignis","translation":"event","pronunciation":"dahs er-IKH-nis","example":"Historisches Ereignis."}]}',
'{"title":"Mit sich bringen — to bring with it/entail","pattern":"etwas bringt etwas mit sich (separable — to bring with it, to entail, involve as a consequence)","explanation":"Mit sich bringen (separable) = to bring with it, entail, involve. Der Job bringt viele Herausforderungen mit sich = The job brings many challenges with it. The Wandel brachte Chancen und Risiken mit sich = The change brought chances and risks with it. Perfect: hat mit sich gebracht. This phrase is very common in formal writing for consequences of change. Also: nach sich ziehen (to entail, bring in its wake — more causal chain).","examples":[{"sentence":"Jede Veränderung bringt neue Möglichkeiten mit sich.","translation":"Every change brings new possibilities with it."},{"sentence":"Die Digitalisierung bringt erhebliche Chancen für die Wirtschaft mit sich.","translation":"Digitisation brings considerable opportunities for the economy with it."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Tiefgreifend'' means?","options":["profound/deep-reaching","fundamental","deep","thorough"],"correctAnswer":"profound/deep-reaching"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Reunification was a historic event that brought with it profound economic and social changes.","options":["Die Wiedervereinigung war ein historisches Ereignis, das tiefgreifende wirtschaftliche und gesellschaftliche Veränderungen mit sich brachte.","Die Wiedervereinigung hat Deutschland sehr verändert.","Die Wiedervereinigung brachte viele Herausforderungen.","Ein historisches Ereignis veränderte Deutschland."],"correctAnswer":"Die Wiedervereinigung war ein historisches Ereignis, das tiefgreifende wirtschaftliche und gesellschaftliche Veränderungen mit sich brachte."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Jede Veränderung bringt neue Möglichkeiten mit ___.","options":["sich","ihm","ihr","einem"],"correctAnswer":"sich"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Digitisation brings considerable opportunities for the economy with it","wordBankItems":["Die","Digitalisierung","bringt","erhebliche","Chancen","für","die","Wirtschaft","mit","sich","."],"correctAnswer":"Die Digitalisierung bringt erhebliche Chancen für die Wirtschaft mit sich ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das Ereignis'' means?","options":["event","occurrence","incident","happening"],"correctAnswer":"event"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000018e',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss memorial culture at B2","Use Erinnerungskultur vocabulary","Reflect on collective memory and responsibility"],"explanation":{"intro":"Memorial culture vocabulary at B2 covers collective memory, memorials, commemoration, and historical responsibility.","culturalNote":"German Erinnerungskultur (memorial culture) is internationally recognised. Key elements: Holocaust-Mahnmal (Berlin Holocaust Memorial), Stolpersteine (stumbling stones — 90,000+ brass plaques across Europe), Gedenkstätten (memorial sites — Dachau, Auschwitz tours), Schuldanerkenntnis (acknowledgment of guilt), Nie wieder (never again). Germany''s approach is often cited as a model for Vergangenheitsbewältigung."},"examples":[{"german":"Die Erinnerungskultur in Deutschland soll verhindern, dass die Verbrechen der Vergangenheit in Vergessenheit geraten.","english":"Memorial culture in Germany is intended to prevent the crimes of the past from falling into oblivion."},{"german":"Gedenkstätten erfüllen eine wichtige pädagogische Funktion für nachfolgende Generationen.","english":"Memorial sites fulfil an important educational function for subsequent generations."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss memorial culture, collective memory, and historical responsibility at B2."}}',
'{"items":[{"word":"in Vergessenheit geraten","translation":"to fall into oblivion","pronunciation":"in fer-GES-en-hyt geh-RAH-ten","example":"In Vergessenheit geraten."},{"word":"die Gedenkstätte","translation":"memorial site","pronunciation":"dee geh-DENK-shtä-teh","example":"Gedenkstätte."},{"word":"pädagogisch","translation":"educational/pedagogical","pronunciation":"pä-dah-GOH-gish","example":"Pädagogische Funktion."},{"word":"nachfolgend","translation":"subsequent/following","pronunciation":"NAKH-fol-gend","example":"Nachfolgende Generationen."},{"word":"das Verbrechen","translation":"crime","pronunciation":"dahs fer-BREKH-en","example":"Verbrechen der Vergangenheit."},{"word":"verhindern","translation":"to prevent","pronunciation":"fer-HIN-dern","example":"Verhindern dass."}]}',
'{"title":"In Vergessenheit geraten — to fall into oblivion","pattern":"in Vergessenheit geraten = to be forgotten, to fall into oblivion (formal, idiom with geraten)","explanation":"In Vergessenheit geraten (geraten = to get into, fall into — with abstract nouns). Geraten takes a destination that describes a state arrived at unexpectedly or gradually. Other geraten patterns: in Verlegenheit geraten (to become embarrassed), in Schwierigkeiten geraten (to get into difficulties), in Konflikt geraten (to come into conflict). All express entering a state somewhat passively. Geraten + past participle (geraten + PP of a motion verb) = end up.","examples":[{"sentence":"Viele Volksmärchen sind im Laufe der Zeit in Vergessenheit geraten.","translation":"Many folk tales have fallen into oblivion over time."},{"sentence":"Die Erkenntnisse der frühen Forschung gerieten lange in Vergessenheit.","translation":"The findings of early research fell into oblivion for a long time."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Pädagogisch'' means?","options":["educational/pedagogical","didactic","academic","instructive"],"correctAnswer":"educational/pedagogical"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Memorial culture in Germany is intended to prevent the crimes of the past from falling into oblivion.","options":["Die Erinnerungskultur in Deutschland soll verhindern, dass die Verbrechen der Vergangenheit in Vergessenheit geraten.","Erinnerungskultur erinnert an vergangene Verbrechen.","Deutschland vergisst seine Vergangenheit nicht.","Gedenkstätten verhindern das Vergessen."],"correctAnswer":"Die Erinnerungskultur in Deutschland soll verhindern, dass die Verbrechen der Vergangenheit in Vergessenheit geraten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Viele Volksmärchen sind im Laufe der Zeit in Vergessenheit ___.","options":["geraten","gegangen","gekommen","gesunken"],"correctAnswer":"geraten"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The findings of early research fell into oblivion for a long time","wordBankItems":["Die","Erkenntnisse","der","frühen","Forschung","gerieten","lange","in","Vergessenheit","."],"correctAnswer":"Die Erkenntnisse der frühen Forschung gerieten lange in Vergessenheit ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Nachfolgend'' means?","options":["subsequent/following","next","later","consecutive"],"correctAnswer":"subsequent/following"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000018f',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss sustainable development at B2","Use Nachhaltigkeit B2 vocabulary","Talk about SDGs and sustainability frameworks"],"explanation":{"intro":"Sustainable development vocabulary at B2 covers the SDGs, sustainability debates, and green economy at advanced level.","culturalNote":"Nachhaltigkeit (sustainability) comes from German forestry (nachhaltige Forstwirtschaft — sustainable forestry, 18th century). UN SDGs (Nachhaltigkeitsziele) frame global policy. Germany has a Nationale Nachhaltigkeitsstrategie. Key tensions: Wohlstandsgesellschaft vs. Degrowth (Postwachstum), Greenwashing concerns, Just Transition (soziale Dimension der Energiewende = social dimension of the energy transition)."},"examples":[{"german":"Nachhaltigkeit bedeutet, die Bedürfnisse der Gegenwart zu befriedigen, ohne die Möglichkeiten künftiger Generationen zu gefährden.","english":"Sustainability means meeting the needs of the present without endangering the opportunities of future generations."},{"german":"Der gerechte Übergang zu einer klimaneutralen Wirtschaft erfordert besondere Rücksicht auf vulnerable Bevölkerungsgruppen.","english":"The just transition to a climate-neutral economy requires special consideration for vulnerable population groups."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss sustainable development, SDGs, and just transition at B2."}}',
'{"items":[{"word":"die Bedürfnisse","translation":"needs","pronunciation":"dee beh-DÜRF-nis-eh","example":"Bedürfnisse befriedigen."},{"word":"gefährden","translation":"to endanger/jeopardise","pronunciation":"geh-FÄR-den","example":"Möglichkeiten gefährden."},{"word":"klimaneutral","translation":"climate-neutral","pronunciation":"KLEE-mah-noy-trahl","example":"Klimaneutrale Wirtschaft."},{"word":"die Rücksicht","translation":"consideration/regard","pronunciation":"dee RÜK-zikht","example":"Rücksicht auf nehmen."},{"word":"vulnerable","translation":"vulnerable","pronunciation":"vool-neh-RAH-bleh","example":"Vulnerable Gruppen."},{"word":"befriedigen","translation":"to satisfy/meet (needs)","pronunciation":"beh-FREE-dee-gen","example":"Bedürfnisse befriedigen."}]}',
'{"title":"Rücksicht nehmen auf — to take consideration for","pattern":"Rücksicht nehmen auf + accusative = to show consideration for, to take into account","explanation":"Rücksicht nehmen auf + accusative = to take consideration for, show regard for. Der Übergang erfordert Rücksicht auf vulnerable Gruppen = The transition requires consideration for vulnerable groups. Die Rücksichtnahme = consideration, regard (noun form). Rücksichtslos = inconsiderate. Rücksichtsvoll = considerate. Also: berücksichtigen (to take into consideration — single verb equivalent): Die Bedürfnisse berücksichtigen = to take needs into account.","examples":[{"sentence":"Wir müssen mehr Rücksicht auf die Bedürfnisse älterer Menschen nehmen.","translation":"We must take more consideration for the needs of older people."},{"sentence":"Die Planung nimmt keine ausreichende Rücksicht auf Umweltfragen.","translation":"The planning does not take sufficient consideration for environmental issues."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Gefährden'' means?","options":["to endanger/jeopardise","to threaten","to harm","to damage"],"correctAnswer":"to endanger/jeopardise"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Sustainability means meeting the needs of the present without endangering the opportunities of future generations.","options":["Nachhaltigkeit bedeutet, die Bedürfnisse der Gegenwart zu befriedigen, ohne die Möglichkeiten künftiger Generationen zu gefährden.","Nachhaltigkeit schützt die Umwelt für künftige Generationen.","Wir müssen nachhaltig leben, um die Zukunft zu sichern.","Für künftige Generationen müssen wir nachhaltig handeln."],"correctAnswer":"Nachhaltigkeit bedeutet, die Bedürfnisse der Gegenwart zu befriedigen, ohne die Möglichkeiten künftiger Generationen zu gefährden."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Wir müssen mehr Rücksicht auf die Bedürfnisse älterer Menschen ___.","options":["nehmen","nehme","zu nehmen","nehmend"],"correctAnswer":"nehmen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The planning does not take sufficient consideration for environmental issues","wordBankItems":["Die","Planung","nimmt","keine","ausreichende","Rücksicht","auf","Umweltfragen","."],"correctAnswer":"Die Planung nimmt keine ausreichende Rücksicht auf Umweltfragen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Berücksichtigen'' is the single-verb equivalent of?","options":["Rücksicht nehmen auf","Rücksicht haben","beachten","achten auf"],"correctAnswer":"Rücksicht nehmen auf"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

-- Lesson 400: B2 Meilenstein 1 (milestone — xp:200, coins:100)
INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000190',1,'APPROVED','PUBLISHED',
'{"objectives":["Review B2 grammar and vocabulary","Demonstrate B2 mastery across all topics","Complete B2 milestone 1"],"explanation":{"intro":"Herzlichen Glückwunsch! You have completed 40 lessons at B2 level. This milestone lesson reviews key B2 grammar and vocabulary from the recent lessons.","culturalNote":"At B2, you can understand the main ideas of complex text on both concrete and abstract topics, including technical discussions in your field of specialisation. You can interact with a degree of fluency and spontaneity that makes regular interaction with native speakers quite possible without strain. Wilkommen in der B2 Welt!"},"examples":[{"german":"Obwohl die Aufgabe schwierig ist, hat das Team sie dank effizienter Zusammenarbeit erfolgreich bewältigt.","english":"Although the task was difficult, the team successfully mastered it thanks to efficient cooperation."},{"german":"Die in den letzten Jahren eingeleiteten Reformen haben grundlegende strukturelle Veränderungen mit sich gebracht.","english":"The reforms introduced in recent years have brought with them fundamental structural changes."}],"rewards":{"xp":200,"coins":100},"metadata":{"estimatedMinutes":25,"canDo":"I can demonstrate B2 competence across grammar, vocabulary, and thematic content — Milestone 1 complete!"}}',
'{"items":[{"word":"bewältigen","translation":"to master/cope with","pronunciation":"beh-VÄL-tee-gen","example":"Eine Aufgabe bewältigen."},{"word":"einleiten","translation":"to initiate/introduce","pronunciation":"YN-ly-ten","example":"Reformen einleiten."},{"word":"die Zusammenarbeit","translation":"cooperation/collaboration","pronunciation":"dee tsoo-ZAM-en-ar-byt","example":"Effiziente Zusammenarbeit."},{"word":"dank","translation":"thanks to (preposition + genitive)","pronunciation":"dank","example":"Dank effizienter Zusammenarbeit."},{"word":"strukturell","translation":"structural","pronunciation":"shtrook-tuh-REL","example":"Strukturelle Veränderungen."},{"word":"grundlegend","translation":"fundamental","pronunciation":"GROONT-lay-gend","example":"Grundlegende Änderungen."}]}',
'{"title":"B2 Milestone — extended participial + mit sich bringen","pattern":"Die in [time] eingeleiteten [noun] haben [result] mit sich gebracht — packing information densely at B2","explanation":"Milestone review of two key B2 patterns: 1) Erweitertes Partizipialattribut: Die [in den letzten Jahren eingeleiteten] Reformen = The [reforms introduced in recent years]. 2) Mit sich bringen: haben tiefgreifende Veränderungen mit sich gebracht = have brought with them profound changes. Combining both in one sentence is a hallmark of B2 written German. Practise parsing and producing these structures.","examples":[{"sentence":"Die von der Regierung angekündigten Maßnahmen haben erhebliche gesellschaftliche Konsequenzen mit sich gebracht.","translation":"The measures announced by the government have brought with them considerable social consequences."},{"sentence":"Die seit Jahren diskutierten Reformen sind nun endlich umgesetzt worden.","translation":"The reforms that have been discussed for years have now finally been implemented."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Dank'' as a preposition takes which case?","options":["genitive (or dative in informal)","dative","accusative","nominative"],"correctAnswer":"genitive (or dative in informal)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Although the task was difficult, the team successfully mastered it thanks to efficient cooperation.","options":["Obwohl die Aufgabe schwierig ist, hat das Team sie dank effizienter Zusammenarbeit erfolgreich bewältigt.","Das Team hat die Aufgabe trotz Schwierigkeiten bewältigt.","Dank guter Zusammenarbeit war die Aufgabe erfolgreich.","Die Aufgabe war schwierig, wurde aber bewältigt."],"correctAnswer":"Obwohl die Aufgabe schwierig ist, hat das Team sie dank effizienter Zusammenarbeit erfolgreich bewältigt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die von der Regierung angekündigten Maßnahmen haben erhebliche Konsequenzen mit sich ___.","options":["gebracht","bringen","getragen","gehabt"],"correctAnswer":"gebracht"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The reforms introduced in recent years have brought with them fundamental structural changes","wordBankItems":["Die","in","den","letzten","Jahren","eingeleiteten","Reformen","haben","grundlegende","strukturelle","Veränderungen","mit","sich","gebracht","."],"correctAnswer":"Die in den letzten Jahren eingeleiteten Reformen haben grundlegende strukturelle Veränderungen mit sich gebracht ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Bewältigen'' means?","options":["to master/cope with","to manage","to handle","to accomplish"],"correctAnswer":"to master/cope with"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

